 37	\begin{definition}\label{def:eVariationOn}
 38	  \mathlibok
 39	  \lean{eVariationOn}
 40	The (extended-real-valued) variation of a function $f : T \to E$ on a set $s$ inside a linear order is the supremum of $\sum_i \mathrm{edist}(f(u_{i+1}, f(u_i)))$ over all finite increasing sequences $u : N \to T$ in $s$.
 41	We denote it by $V_f(s)$~.
 42	\end{definition}
 43	
