 45	\begin{definition}\label{def:BoundedVariationOn}
 46	  \uses{def:eVariationOn}
 47	  \mathlibok
 48	  \lean{BoundedVariationOn}
 49	A function $f : T \to E$ is of bounded variation on a set $s$ if its variation $V_f(s)$ is finite.
 50	\end{definition}
