 53	\begin{definition}\label{def:LocallyBoundedVariationOn}
 54	  \uses{def:BoundedVariationOn}
 55	  \mathlibok
 56	  \lean{LocallyBoundedVariationOn}
 57	A function $f : T \to E$ is of locally bounded variation on a set $s$ if for every $a, b$ in $s$, the variation $V_f(s \cap [a, b])$ is finite.
 58	\end{definition}
