122	\section{Square integrable martingales}
123	
124	In this section, $E$ denotes a complete normed space.
125	
126	\begin{definition}[Square integrable martingales]\label{def:IsSquareIntegrable}
127	  \uses{def:Martingale}
128	  \leanok
129	  \lean{ProbabilityTheory.IsSquareIntegrable}
130	Let $T$ be a linear order with bottom element 0, on which we have a filtration $\mathcal{F}$ satisfying the usual conditions.
131	We say that a martingale $M : T \to \Omega \to E$ is square integrable if it is càdlàg and $\sup_{t \in T} \Vert M_t \Vert_{L^2} < \infty$ (Lean remark: use \texttt{eLpNorm (M t) 2}).
132	\end{definition}
133	
134	
135	\begin{lemma}\label{lem:IsSquareIntegrable.module}
136	  \uses{def:IsSquareIntegrable}
137	  \lean{ProbabilityTheory.IsSquareIntegrable.add, ProbabilityTheory.IsSquareIntegrable.smul}
138	If $M$ and $N$ are square integrable martingales and $a \in \mathbb{R}$, then $M + N$ and $a M$ are square integrable martingales.
139	\end{lemma}
